// ===========================================================================
//  CẤU HÌNH
// ===========================================================================
// Nguồn tin RSS (thêm/bớt tuỳ ý). Nếu nguồn nào chết, xem mảng debug ở OUTPUT.
const FEEDS = [
  { name: 'CafeF - Chứng khoán', url: 'https://cafef.vn/thi-truong-chung-khoan.rss' },
  { name: 'CafeF - Tài chính NH', url: 'https://cafef.vn/tai-chinh-ngan-hang.rss' },
  { name: 'CafeF - Doanh nghiệp',  url: 'https://cafef.vn/doanh-nghiep.rss' },
  { name: 'CafeF - Vĩ mô',         url: 'https://cafef.vn/vi-mo-dau-tu.rss' },
];

// Danh mục theo dõi - để Claude ưu tiên tin liên quan các mã này
const WATCHLIST = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'SSI', 'DGC', 'VND', 'MBB', 'STB'];

const MAX_PER_FEED  = 8;    // số tin lấy mỗi nguồn
const MAX_AGE_HOURS = 30;   // chỉ lấy tin trong N giờ gần nhất (30h để phủ qua đêm/cuối tuần)
// ===========================================================================

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/rss+xml, application/xml, text/xml, */*',
};
const cutoff = Date.now() - MAX_AGE_HOURS * 3600 * 1000;

// Lấy nội dung 1 thẻ XML đầu tiên, bỏ CDATA và tag con
const pick = (xml, tag) => {
  const m = xml.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  if (!m) return '';
  return m[1]
    .replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
};

const items = [];
const debug = [];

for (const f of FEEDS) {
  try {
    const body = await this.helpers.httpRequest({ method: 'GET', url: f.url, headers, json: false });
    const xml  = typeof body === 'string' ? body : String(body);
    const blocks = xml.match(/<item[\s\S]*?<\/item>/gi) || [];
    let count = 0;
    for (const it of blocks) {
      if (count >= MAX_PER_FEED) break;
      const title = pick(it, 'title');
      const pub   = pick(it, 'pubDate');
      const desc  = pick(it, 'description').slice(0, 280);
      const t = pub ? new Date(pub).getTime() : Date.now();
      if (title && (!pub || isNaN(t) || t >= cutoff)) {
        items.push({ source: f.name, title, desc });
        count++;
      }
    }
    debug.push(f.name + ': ' + count + ' tin');
  } catch (e) {
    debug.push(f.name + ': ❌ ' + (e.message || String(e)));
  }
}

const newsText = items.length
  ? items.map((x, i) => (i + 1) + '. [' + x.source + '] ' + x.title + (x.desc ? '\n   ' + x.desc : '')).join('\n\n')
  : '(Không lấy được tin nào - kiểm tra mảng debug, có thể URL RSS đã đổi)';

const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', weekday: 'long', day: 'numeric', month: 'numeric', year: 'numeric' });

const system = 'Bạn là chuyên viên phân tích chứng khoán Việt Nam, hỗ trợ một nhà đầu tư cá nhân. '
  + 'Nhiệm vụ: đọc tin tức thị trường, lọc nhiễu, viết BÁO CÁO SÁNG ngắn gọn bằng tiếng Việt.\n\n'
  + 'Nguyên tắc bắt buộc:\n'
  + '- Ưu tiên tin tác động tới danh mục theo dõi: ' + WATCHLIST.join(', ') + '.\n'
  + '- Với mỗi tin quan trọng: nêu mã/ngành liên quan, tóm tắt 1 dòng, đánh giá tác động (Tích cực/Tiêu cực/Trung tính) kèm mức độ tin cậy (cao/trung bình/thấp).\n'
  + '- Bố cục: (1) 🔥 Tin nóng tác động watchlist, (2) 🌐 Bối cảnh thị trường chung, (3) ⚠️ Cảnh báo rủi ro (nếu có).\n'
  + '- TUYỆT ĐỐI KHÔNG khuyến nghị mua/bán cụ thể. KHÔNG bịa số liệu. Tin chưa rõ thì ghi "cần kiểm chứng".\n'
  + '- Ngắn gọn, dễ đọc trên điện thoại. Dùng Markdown đơn giản (*đậm*, gạch đầu dòng). Tối đa ~500 từ.';

const userContent = 'Hôm nay là ' + today + '. Dưới đây là tin tức thu thập được sáng nay:\n\n'
  + newsText
  + '\n\nHãy viết báo cáo sáng theo đúng bố cục yêu cầu. Nếu phần tin trống, nói rõ là chưa lấy được tin.';

const requestBody = {
  model: 'claude-opus-4-8',
  max_tokens: 4000,
  system,
  messages: [{ role: 'user', content: userContent }],
};

return [{ json: { requestBody, itemCount: items.length, debug } }];

// Trích phần text từ phản hồi Claude và cắt nhỏ cho vừa giới hạn Telegram (4096 ký tự/tin)
const res = $input.first().json;

let text = '';
if (res && Array.isArray(res.content)) {
  text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
}

// Bắt lỗi API hoặc bị từ chối
if (!text) {
  if (res && res.type === 'error' && res.error) {
    text = '⚠️ Lỗi API: ' + (res.error.message || JSON.stringify(res.error));
  } else if (res && res.stop_reason === 'refusal') {
    text = '⚠️ Yêu cầu bị từ chối bởi bộ lọc an toàn.';
  } else {
    text = '⚠️ Không tạo được báo cáo (phản hồi rỗng).';
  }
}

const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const full = '☀️ *BÁO CÁO SÁNG THỊ TRƯỜNG*\n_' + now + '_\n\n' + text + '\n\n_Nguồn: CafeF · Tổng hợp bởi Claude AI · không phải khuyến nghị đầu tư_';

// Cắt thành các đoạn <= 3800 ký tự, ưu tiên cắt ở dấu xuống dòng
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) {
  let cut = s.lastIndexOf('\n', SIZE);
  if (cut < SIZE * 0.5) cut = SIZE;
  parts.push(s.slice(0, cut));
  s = s.slice(cut);
}
if (s.trim()) parts.push(s);

return parts.map(p => ({ json: { message: p } }));
